from typing import Dict, Any
from dataclasses import dataclass

@dataclass
class SecretPayload:
    project_id: str
    secret_id: str
    version_id: str = "latest"

@dataclass
class SecretResponse:
    secret_id: str
    version_id: str
    data: str | Dict[str, Any]

def normalize_json_secret(secret_data: str) -> Dict[str, Any]:
    """
    Normalizes a JSON string secret into a dictionary.
    """
    import json
    return json.loads(secret_data)

def normalize_text_secret(secret_data: str) -> str:
    """
    Normalizes a text secret.
    """
    return secret_data

from google.cloud import secretmanager

def check_secret_label_safety(project_id: str, secret_id: str, unsafe_keywords: list[str]) -> dict:
    """
    Checks secret labels for unsafe text based on a list of keywords.
    """
    client = secretmanager.SecretManagerServiceClient()
    name = f"projects/{project_id}/secrets/{secret_id}"
    secret = client.get_secret(request={"name": name})

    unsafe_findings = []
    for key, value in secret.labels.items():
        for keyword in unsafe_keywords:
            if keyword.lower() in key.lower() or keyword.lower() in value.lower():
                unsafe_findings.append({"label_key": key, "label_value": value, "found_keyword": keyword})

    return {"secret_id": secret_id, "unsafe_label_findings": unsafe_findings}

from google.cloud import translate_v3 as translate

def translate_runbook_notes(project_id: str, notes: str, target_language_code: str = "es") -> dict:
    """
    Translates secret-rotation runbook notes using Google Cloud Translation API.
    """
    client = translate.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [notes],
            "target_language_code": target_language_code,
        }
    )

    translated_text = response.translations[0].translated_text if response.translations else notes

    return {
        "original_notes": notes,
        "target_language": target_language_code,
        "translated_notes": translated_text
    }
